// Builds one alert per error event and decides whether it may be sent now.
// Identical errors (same workflow, node and message pattern) are sent at most
// once per cooldown window; the next alert reports how many were held back.
const settings = $('Settings').first().json;
const event = $('On workflow error').first().json;

const cooldownInput = Number(settings.cooldownMinutes);
const cooldownMs = (Number.isFinite(cooldownInput) && cooldownInput >= 0 ? cooldownInput : 60) * 60 * 1000;

const workflow = event.workflow || {};
const execution = event.execution || null;
const trigger = event.trigger || null;
const executionError = execution && execution.error ? execution.error : null;
const triggerError = trigger && trigger.error ? trigger.error : null;
const error = executionError || triggerError || {};
const isTriggerError = !executionError && !!triggerError;

const workflowName = String(workflow.name || 'Unknown workflow');
const workflowId = String(workflow.id || 'unknown');
const nodeName = String((error.node && error.node.name) || (execution && execution.lastNodeExecuted) || (isTriggerError ? 'Trigger' : 'Unknown node'));
const errorName = String(error.name || 'Error');
const message = String(error.message || 'No error message');
const executionId = execution && execution.id ? String(execution.id) : '';
const executionUrl = execution && typeof execution.url === 'string' && /^https?:\/\//.test(execution.url) ? execution.url : '';

// Numbers and whitespace are normalised so "timeout after 3012 ms" and
// "timeout after 2950 ms" count as the same problem.
const pattern = message.replace(/\d+/g, '#').replace(/\s+/g, ' ').trim().slice(0, 200);
const fingerprint = [workflowId, nodeName, errorName, pattern].join(' | ');

const state = $getWorkflowStaticData('global');
if (!state.alerts || typeof state.alerts !== 'object' || Array.isArray(state.alerts)) state.alerts = {};
const now = Date.now();
const keepMs = Math.max(cooldownMs, 24 * 60 * 60 * 1000) * 2;
for (const [key, entry] of Object.entries(state.alerts)) {
  const valid = entry && Number.isFinite(entry.lastSentAt) && entry.lastSentAt <= now;
  if (!valid || now - entry.lastSentAt > keepMs) delete state.alerts[key];
}

const previous = state.alerts[fingerprint];
let sendNow = true;
let heldBack = 0;
if (previous && now - previous.lastSentAt < cooldownMs) {
  previous.suppressed = (Number(previous.suppressed) || 0) + 1;
  sendNow = false;
} else {
  heldBack = previous ? Number(previous.suppressed) || 0 : 0;
  state.alerts[fingerprint] = { lastSentAt: now, suppressed: 0 };
}

const escapeHtml = (value) => String(value).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const oneLine = (value) => String(value).replace(/[\r\n]+/g, ' ').trim();

const kind = isTriggerError ? 'Trigger or activation error' : 'Node error';
const subject = oneLine('[n8n] ' + workflowName + ' failed' + (isTriggerError ? ' (trigger)' : ' at ' + nodeName)).slice(0, 180);
const rows = [
  ['Workflow', workflowName + ' (' + workflowId + ')'],
  ['Type', kind],
  ['Node', nodeName],
  ['Error', errorName + ': ' + message.slice(0, 1000)],
  ['Execution', executionId || 'none (trigger error)'],
  ['Time (UTC)', new Date(now).toISOString()],
];
if (heldBack > 0) rows.push(['Held back', heldBack + ' identical alert(s) since the last email']);
if (isTriggerError) rows.push(['Next step', 'Open the workflow and check that it is still active.']);

const html = '<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;color:#1f2328;max-width:640px;width:100%;box-sizing:border-box;overflow-wrap:anywhere;word-break:break-word;">'
  + '<p><strong>' + escapeHtml(subject) + '</strong></p>'
  + '<table role="presentation" style="width:100%;table-layout:fixed;border-collapse:collapse">'
  + rows.map(([k, v]) => '<tr><td style="width:28%;padding:4px 12px 4px 0;vertical-align:top;color:#57606a;overflow-wrap:anywhere;word-break:break-word;">' + escapeHtml(k) + '</td><td style="padding:4px 0;vertical-align:top;overflow-wrap:anywhere;word-break:break-word;">' + escapeHtml(v) + '</td></tr>').join('')
  + '</table>'
  + (executionUrl ? '<p><a href="' + escapeHtml(executionUrl) + '">Open the failed execution</a></p>' : '')
  + '<p style="color:#57606a;font-size:12px">Identical errors are sent at most once every ' + Math.round(cooldownMs / 60000) + ' minutes.</p>'
  + '</div>';
const text = rows.map(([k, v]) => k + ': ' + v).join('\n') + (executionUrl ? '\nExecution URL: ' + executionUrl : '');

return [{ json: { sendNow, subject, html, text, fingerprint, heldBack } }];

// The alert email could not be sent. Remove the cooldown entry so the next
// occurrence of this error is not silently suppressed.
const state = $getWorkflowStaticData('global');
const fingerprint = $('Build alert').first().json.fingerprint;
if (state.alerts && fingerprint && Object.prototype.hasOwnProperty.call(state.alerts, fingerprint)) {
  delete state.alerts[fingerprint];
}
return [{ json: { cooldownReleased: true, fingerprint } }];

