Workflow: {{ $('On workflow error').item.json.workflow?.name ?? 'unknown' }} ({{ $('On workflow error').item.json.workflow?.id ?? 'unknown' }})
Execution: {{ $('On workflow error').item.json.execution?.id ?? 'none (trigger error)' }}
Last node: {{ $('On workflow error').item.json.execution?.lastNodeExecuted ?? 'unknown' }}
Time (UTC): {{ $now.toUTC().toISO() }}

